                <h3 className="mb-4 text-xl font-bold text-black dark:text-white sm:text-2xl lg:text-xl xl:text-2xl">
                  🔹 1.3 ክርስትና ማለት ክርስቶስን መከተል ከሆነ፤ ክርስቶስ ማነው?ክርስቶስ
                    ለእኛስ መቼ ተከተሉኝ መቼ አለ ? ጥሪ መቼ አቀረበ?

                </h3>
